import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        String[][] ops = new String[(int) n][3];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        int cap = (int) m;
        long[] vals = new long[cap], add = new long[cap];
        int size = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String op = ops[i][0];
            if (op.equals("push")) {
                if (size < cap) {
                    vals[size] = Long.parseLong(ops[i][1]);
                    add[size] = 0;
                    size++;
                }
            } else if (op.equals("pop")) {
                if (size == 0) {
                    sb.append(-1).append("\n");
                } else {
                    size--;
                    sb.append(vals[size] + add[size]).append("\n");
                    if (size > 0) add[size - 1] += add[size];
                    add[size] = 0;
                }
            } else {
                if (size > 0) add[(int) Math.min(size, Long.parseLong(ops[i][1])) - 1] += Long.parseLong(ops[i][2]);
            }
        }
        System.out.print(sb);
    }
}
